import{_ as t,o as s,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Conversion","description":"","frontmatter":{"title":"Conversion"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/conversion.md","filePath":"fr/projects/blocks-for-ha/conversion.md","lastUpdated":1793125707000}'),o={name:"fr/projects/blocks-for-ha/conversion.md"};function a(i,e,d,l,u,c){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="conversion" tabindex="-1">Conversion <a class="header-anchor" href="#conversion" aria-label="Permalink to &quot;Conversion&quot;">​</a></h1><p>Les conversions sont évaluées dans <strong>HA/Jinja</strong>. Elles ne reposent pas sur les coercitions de JavaScript. <a href="./blocks">Catalogue illustré</a>.</p><table tabindex="0"><thead><tr><th>Bloc</th><th>Résultat et limites</th></tr></thead><tbody><tr><td>Convertir en nombre</td><td><code>float()</code> HA exige une valeur numérique complète. Pas de préfixe <code>parseFloat</code> ni de valeur de secours implicite.</td></tr><tr><td>Convertir en booléen</td><td><code>bool()</code> HA reconnaît true/false, on/off, yes/no, 1/0. Valeur non reconnue : erreur.</td></tr><tr><td>Convertir en texte</td><td>Représentation Jinja ; booléens True/False. Ce n’est pas une sérialisation JSON.</td></tr><tr><td>Type de</td><td><code>typeof()</code> HA retourne les types Python : str, int, float, bool, dict, list, NoneType. HA ≥ 2023.4.</td></tr><tr><td>Convertir en date/heure</td><td>Texte ISO, secondes Unix ou millisecondes Unix. Préférer un fuseau explicite ; résultat en heure locale HA.</td></tr><tr><td>Formater date/heure</td><td>Objet date, texte ISO, formats d’heure/date, unités Unix, composantes de calendrier ou format personnalisé. Le raccord change selon le résultat.</td></tr><tr><td>Durée</td><td>Millisecondes ou secondes vers hh:mm:ss, hh:mm ou mm:ss. Fractions tronquées ; heures/minutes peuvent dépasser 24/60, signe conservé.</td></tr><tr><td>JSON vers valeur</td><td>Objet, liste ou valeur JSON simple. JSON invalide : erreur.</td></tr><tr><td>Valeur vers JSON</td><td>Sérialisation HA avec indentation facultative. Convertir les dates auparavant.</td></tr></tbody></table><p>Les formats personnalisés utilisent <strong>Python strftime</strong> : <code>%Y</code>, <code>%m</code>, <code>%d</code>, <code>%H</code>, <code>%M</code>, <code>%S</code>. Les formats de date ioBroker ne sont pas directement interchangeables.</p><p>Une conversion numérique produit un nombre à l’exécution. Elle peut alimenter calculs, variables et conditions de modèle, mais pas les seuils fixes des déclencheurs numériques. Les comparaisons de capteurs doivent convertir leurs états textuels explicitement.</p><p>Les allers-retours de projet/YAML conservent les formats pris en charge. JSONata n’est pas proposé sans moteur réellement disponible à l’exécution dans HA. <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">Documentation des modèles HA</a> · <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">Référence ioBroker</a>.</p><details class="details custom-block"><summary>Référence détaillée issue de la documentation allemande</summary><h2 id="konvertierung" tabindex="-1">Conversion <a class="header-anchor" href="#konvertierung" aria-label="Permalink to &quot;Conversion {#konvertierung}&quot;">​</a></h2><p>Depuis la version <strong>0.1.12</strong>, cette catégorie propose neuf nouveaux blocs. <a href="/fr/projects/blocks-for-ha/blocks#konvertierung-seit-0-1-12">Voir tous les blocs de conversion en images</a>. Leur fonctionnement est basé sur celui des <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_convert.ts" target="_blank" rel="noreferrer">blocs de conversion ioBroker</a>. Ces blocs utilisent la bibliothèque Blockly originale, avec une traduction spécifique UGSo vers le langage Jinja de Home Assistant. La conversion effective a lieu uniquement lors de l&#39;exécution dans Home Assistant.</p><h3 id="iobroker-ugso-blocks-fur-ha" tabindex="-1">Blocs ioBroker / UGSo pour HA <a class="header-anchor" href="#iobroker-ugso-blocks-fur-ha" aria-label="Permalink to &quot;Blocs ioBroker / UGSo pour HA {#iobroker-ugso-blocks-fur-ha}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ioBroker</th><th>Notre bloc</th><th>Comportement / Différence</th></tr></thead><tbody><tr><td>en nombre</td><td><strong>En nombre</strong></td><td>HA <code>float</code> : convertit une valeur numérique complète. <code>21.5</code> fonctionne ; <code>21W</code> et la virgule décimale ne fonctionnent pas. Contrairement à <code>parseFloat</code>, aucun préfixe numérique n&#39;est extrait.</td></tr><tr><td>en valeur logique</td><td><strong>En valeur logique</strong></td><td>HA <code>bool</code> : booléen ou valeurs reconnues telles que true/false, on/off, yes/no et 1/0. Les textes inconnus ne sont pas considérés automatiquement comme une valeur « vrai ».</td></tr><tr><td>en chaîne de caractères</td><td><strong>En chaîne de caractères</strong></td><td>Représentation textuelle Jinja. Un booléen donne par exemple <code>True</code>/<code>False</code> ; la représentation JSON des objets n&#39;est pas garantie.</td></tr><tr><td>type de</td><td><strong>Type de</strong></td><td>HA <code>typeof</code>, à partir de HA 2023.4. Renvoie les noms de types Python (str, int, float, bool, dict, list, NoneType) au lieu des noms de types JavaScript.</td></tr><tr><td>en date/heure</td><td><strong>En date/heure</strong></td><td>Texte au format ISO ou secondes/millisecondes Unix spécifiées → valeur de date selon l&#39;heure locale de HA. Utiliser le format ISO avec « Z » ou un décalage (offset).</td></tr><tr><td>date/heure en…</td><td><strong>Date/heure en…</strong></td><td>Valeur de date, format ISO/heure/date, nombre Unix, année/mois/jour/heure/minute/seconde/milliseconde, jour de la semaine, numéro de semaine ou temps écoulé depuis minuit. L&#39;option « format personnalisé » fait apparaître un champ de texte supplémentaire.</td></tr><tr><td>formater la différence de temps</td><td><strong>Formater la différence de temps</strong></td><td>Durée numérique exprimée en millisecondes (par défaut) ou en secondes. Formats hh:mm:ss, hh:mm, mm:ss. Les durées négatives conservent leur signe ; les valeurs d&#39;heures ou de minutes élevées ne subissent pas de conversion modulo 24 ou 60.</td></tr><tr><td>JSON vers objet</td><td><strong>JSON vers valeur</strong></td><td><code>from_json</code>, prend également en charge les listes et les valeurs isolées. Un JSON invalide génère une erreur de modèle ; aucun objet de remplacement vide n&#39;est créé silencieusement.</td></tr><tr><td>Objet vers JSON, avec formatage</td><td><strong>Valeur vers JSON, avec formatage</strong></td><td><code>to_json</code>, avec une case à cocher pour l&#39;indentation. Seules les valeurs sérialisables en JSON sont acceptées ; les dates doivent être converties au préalable au format ISO ou en nombre Unix.</td></tr><tr><td>Appliquer une expression JSONata à</td><td><strong>En attente</strong></td><td>Aucun adaptateur d&#39;exécution JSONata n&#39;est disponible dans l&#39;éditeur. Les modèles HA personnalisés peuvent déjà utiliser Jinja pour accéder aux valeurs d&#39;objets ou de listes. Une véritable intégration de JSONata doit également être fonctionnelle lors de l&#39;exécution ultérieure dans HA.</td></tr></tbody></table><p>Références pour les règles HA : <a href="https://www.home-assistant.io/template-functions/float/" target="_blank" rel="noreferrer">float</a>, <a href="https://www.home-assistant.io/template-functions/bool/" target="_blank" rel="noreferrer">bool</a>, <a href="https://www.home-assistant.io/template-functions/typeof/" target="_blank" rel="noreferrer">typeof</a>, <a href="https://www.home-assistant.io/template-functions/from_json/" target="_blank" rel="noreferrer">from_json</a>, <a href="https://www.home-assistant.io/template-functions/to_json/" target="_blank" rel="noreferrer">to_json</a>.</p><h3 id="anschlusse-und-formatfelder" tabindex="-1">Connexions et champs de formatage <a class="header-anchor" href="#anschlusse-und-formatfelder" aria-label="Permalink to &quot;Connexions et champs de formatage {#anschlusse-und-formatfelder}&quot;">​</a></h3><p>Les valeurs booléennes sont compatibles avec les conditions et la logique. Les nombres convertis sont des <strong>nombres dynamiques (valeurs d&#39;exécution)</strong> : ils peuvent être utilisés dans des comparaisons de valeurs, des variables, le formatage de durées, ainsi que pour définir des montants ou des décalages dans les blocs temporels. En revanche, les seuils fixes (<code>numeric-state</code>), les temps d&#39;attente et les incréments nécessitent toujours des blocs de type « nombre » (constantes). Il est donc impossible d&#39;y connecter par erreur des nombres dynamiques. La configuration dynamique de la haute disponibilité (HA) pour ces champs n&#39;est pas encore implémentée.</p><p>Les valeurs de date utilisent le connecteur « Time ». Dans le bloc <strong>Date/Heure vers…</strong>, la sélection détermine la sortie : valeur de date, nombre (durée) ou texte. Le format personnalisé utilise Python <code>strftime</code> avec <code>%Y</code>, <code>%m</code>, <code>%d</code>, <code>%H</code>, <code>%M</code>, <code>%S</code>. Les codes de formatage ioBroker, tels que <code>YYYY</code>, ne sont pas interchangeables. Les noms des mois et des jours de la semaine (dépendants de la langue), les autres formats de durée ainsi qu&#39;un masque de durée personnalisé ne sont pas encore implémentés. Pour les jours de la semaine, le comptage va de lundi=1 à dimanche=7 ; le numéro de semaine suit la norme ISO. Les fractions de seconde dans une durée sont tronquées, et non arrondies.</p><h3 id="beispiele" tabindex="-1">Exemples <a class="header-anchor" href="#beispiele" aria-label="Permalink to &quot;Exemples {#beispiele}&quot;">​</a></h3><p>Convertir le texte d&#39;un capteur en nombre et le comparer à 20 : Valeur de modèle (template) avec état du capteur → Vers nombre → Comparaison. La sortie HA contient :</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ (</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">((</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">states</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sensor.temperatur&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">))) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 20) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Texte JSON → JSON vers valeur → Valeur vers JSON (formatage) :</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ ((</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;wert&quot;:21.5}&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> | </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">from_json</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) | </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">to_json</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pretty_print</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">)) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Une différence temporelle de <code>3661000</code> millisecondes devient <code>01:01:01</code> ; <code>-3661000</code> devient <code>-01:01:01</code>. Il convient de bien distinguer les millisecondes des secondes. Le bloc formate une durée déjà existante ; il ne calcule pas automatiquement la différence entre deux valeurs de date.</p><h3 id="fehler-speichern-und-offene-erweiterung" tabindex="-1">Erreurs, enregistrement et développements futurs <a class="header-anchor" href="#fehler-speichern-und-offene-erweiterung" aria-label="Permalink to &quot;Erreurs, enregistrement et développements futurs {#fehler-speichern-und-offene-erweiterung}&quot;">​</a></h3><p>Les blocs n&#39;attribuent pas de valeurs par défaut implicites en cas de nombre, de booléen ou de JSON invalide. Si une valeur de remplacement est nécessaire, elle peut être définie explicitement dans le modèle (template) HA général. Les variables HA peuvent interpréter les résultats des modèles comme des valeurs natives ; la spécification d&#39;un type « chaîne de caractères » (string) constitue une information destinée à l&#39;éditeur, mais ne garantit pas que HA n&#39;appliquera pas sa propre interprétation de type lors de l&#39;enregistrement d&#39;un résultat.</p><p>Les projets JSON conservent leurs formes de blocs, leurs cases à cocher et leur format spécifique. Lors de l&#39;ouverture au format YAML, ces expressions sont préservées sous forme de blocs de modèle (template) génériques. Les conversions effectuées au sein d&#39;une action sur une variable peuvent générer des objets ou des listes lors de l&#39;exécution ; en revanche, les variables de type objet ou liste enregistrées directement en YAML ne sont toujours pas importables. L&#39;action HA générique attend actuellement des données d&#39;action JSON statiques ; il n&#39;est pas encore possible d&#39;y intégrer directement des blocs de conversion.</p><p><strong>En attente :</strong> Extension de la gestion des accès aux objets/listes, suivie de l&#39;examen d&#39;un adaptateur d&#39;exécution JSONata optionnel. Une évaluation effectuée uniquement dans le navigateur ne refléterait pas le comportement d&#39;une automatisation exécutée ultérieurement au sein de HA.</p><p>Les cycles de conversion entre Blockly et YAML, les vérifications de connexions et l&#39;évaluation Jinja (utilisant des fonctions d&#39;assistance HA simulées) ont été testés. L&#39;exécution sur un véritable système HA n&#39;a pas encore été vérifiée.</p></details>',7)])])}const h=t(o,[["render",a]]);export{m as __pageData,h as default};
